per_hop.query:
SELECT ?winnerBirthDate WHERE {
  ?tournament wdt:P31 wd:Q189122 ;           # instance of tennis tournament
              rdfs:label "1980 Lorraine Open"@en ;
              wdt:P1346 ?winner .             # has winner
  ?winner wdt:P569 ?winnerBirthDate .          # date of birth
}
LIMIT 1

# Serena Williams date of birth: 1981-09-26

SELECT 
  (SELECT COUNT(*) FROM albums WHERE artist = 'Candlelight Red') AS candlelight_red_album_count,
  (SELECT COUNT(*) FROM albums WHERE artist = 'One Unique Signal') AS one_unique_signal_album_count;
